/* The input captured by a widget that is not attached to a root window.

   A button takes the input when it gets a pen down. A pen down sent with the
   button as its target reaches it wherever the button is, so a button that is
   not attached to any root window can own the input. Later pen events then go
   to the owner, and the dispatcher looks for the owner's root window to adjust
   the pen position by that root's canvas offset.

   1. A button with no parent takes the input. A pen drag must reach it with
      its position as sent: there is no root, so nothing to adjust by. The
      button is then deleted while it owns the input. The capture must go with
      it: the next pen down and up over the root's own button must reach that
      button and not the deleted one.

   2. A button inside a window that has no parent takes the input. The top of
      its tree is that window, which is not a root window, and must not be
      read as one. The window is followed in memory by a pointer to a canvas
      whose display offset is 1000 pixels, placed where a root window keeps its
      canvas pointer. A pen drag must reach the button with its position as
      sent; read as a root, the window would make it 1000 pixels off.

   The events are dispatched as the GUIX thread dispatches them, through
   _gx_system_event_dispatch, so each one is delivered before the next step. */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stddef.h>
#include "tx_api.h"
#include "gx_api.h"
#include "gx_system.h"
#include "gx_validation_utility.h"

TEST_PARAM test_parameter = {
    "guix_input_capture_outside_root_no_output", /* Test name */
    0, 0, 0, 0  /* Define the coordinates of the capture area.*/
};

int main(int argc, char ** argv)
{
    /* Start ThreadX system */
    tx_kernel_enter();
    return(0);
}

UINT gx_validation_graphics_driver_setup_565rgb(GX_DISPLAY *display);

/* A window followed by what a root window keeps after its window members.  */
typedef struct TEST_TRAP_STRUCT
{
    GX_WINDOW  test_trap_window;
    GX_CANVAS *test_trap_canvas;
} TEST_TRAP;

static UINT           failed_tests = 0;

static TX_THREAD      test_thread;
static ULONG          test_thread_stack[8192 / sizeof(ULONG)];

static GX_DISPLAY     test_display;
static GX_CANVAS      test_canvas;
static USHORT         test_canvas_memory[160 * 120];
static GX_WINDOW_ROOT test_root;
static GX_BUTTON      test_root_button;
static GX_BUTTON      test_button;
static TEST_TRAP      test_trap;
static GX_CANVAS      test_trap_canvas;
static GX_DISPLAY     test_trap_display;

/* Pen events each button received, and where the last one was.  */
static INT            test_root_button_events;
static INT            test_button_events;
static GX_POINT       test_last_position;

static UINT test_button_event_process(GX_WIDGET *widget, GX_EVENT *event_ptr)
{
    switch (event_ptr -> gx_event_type)
    {
    case GX_EVENT_PEN_DOWN:
    case GX_EVENT_PEN_DRAG:
    case GX_EVENT_PEN_UP:
        if (widget == (GX_WIDGET *)&test_root_button)
        {
            test_root_button_events++;
        }
        else
        {
            test_button_events++;
        }
        test_last_position = event_ptr -> gx_event_payload.gx_event_pointdata;
        break;
    }

    return gx_button_event_process((GX_BUTTON *)widget, event_ptr);
}

static VOID test_pen(ULONG type, GX_WIDGET *target, GX_VALUE x, GX_VALUE y)
{
GX_EVENT event;

    memset(&event, 0, sizeof(GX_EVENT));
    event.gx_event_type = type;
    event.gx_event_target = target;
    event.gx_event_payload.gx_event_pointdata.gx_point_x = x;
    event.gx_event_payload.gx_event_pointdata.gx_point_y = y;
    event.gx_event_display_handle = (ULONG)test_display.gx_display_driver_data;
    _gx_system_event_dispatch(&event);
}

static VOID test_owner_check(char *label, GX_WIDGET *owner)
{
    if (owner)
    {
        if ((_gx_system_capture_count != 1) || (_gx_system_input_capture_stack[0] != owner))
        {
            printf("%s: the button does not own the input (capture count %d)\n", label, _gx_system_capture_count);
            failed_tests++;
        }
    }
    else if (_gx_system_capture_count != 0)
    {
        printf("%s: the input is still captured (capture count %d)\n", label, _gx_system_capture_count);
        failed_tests++;
    }
}

static VOID test_position_check(char *label, GX_VALUE x, GX_VALUE y)
{
    if ((test_last_position.gx_point_x != x) || (test_last_position.gx_point_y != y))
    {
        printf("%s: pen position (%d, %d), sent (%d, %d)\n", label, test_last_position.gx_point_x,
               test_last_position.gx_point_y, x, y);
        failed_tests++;
    }
}

static VOID test_thread_entry(ULONG id)
{
GX_RECTANGLE size;

    gx_system_initialize();

    EXPECT_EQ(GX_SUCCESS, gx_display_create(&test_display, "test_display", gx_validation_graphics_driver_setup_565rgb, 160, 120));
    EXPECT_EQ(GX_SUCCESS, gx_canvas_create(&test_canvas, "test_canvas", &test_display, GX_CANVAS_SIMPLE | GX_CANVAS_VISIBLE,
                                           160, 120, (GX_COLOR *)test_canvas_memory, sizeof(test_canvas_memory)));
    gx_utility_rectangle_define(&size, 0, 0, 159, 119);
    EXPECT_EQ(GX_SUCCESS, gx_window_root_create(&test_root, "test_root", &test_canvas, GX_STYLE_NONE, GX_ID_NONE, &size));
    gx_utility_rectangle_define(&size, 10, 10, 60, 40);
    EXPECT_EQ(GX_SUCCESS, gx_button_create(&test_root_button, "test_root_button", &test_root, GX_STYLE_ENABLED, GX_ID_NONE, &size));
    gx_widget_event_process_set(&test_root_button, test_button_event_process);
    EXPECT_EQ(GX_SUCCESS, gx_widget_show(&test_root));

    /* 1. A button with no parent.  */
    gx_utility_rectangle_define(&size, 70, 50, 120, 80);
    EXPECT_EQ(GX_SUCCESS, gx_button_create(&test_button, "test_button", GX_NULL, GX_STYLE_ENABLED, GX_ID_NONE, &size));
    gx_widget_event_process_set(&test_button, test_button_event_process);

    test_pen(GX_EVENT_PEN_DOWN, (GX_WIDGET *)&test_button, 80, 60);
    test_owner_check("no parent, pen down", (GX_WIDGET *)&test_button);

    test_pen(GX_EVENT_PEN_DRAG, GX_NULL, 81, 61);
    EXPECT_EQ(2, test_button_events);
    test_position_check("no parent, pen drag", 81, 61);

    EXPECT_EQ(GX_SUCCESS, gx_widget_delete(&test_button));
    test_owner_check("no parent, deleted", GX_NULL);

    test_button_events = 0;
    test_pen(GX_EVENT_PEN_DOWN, GX_NULL, 20, 20);
    test_owner_check("root's button, pen down", (GX_WIDGET *)&test_root_button);
    test_pen(GX_EVENT_PEN_UP, GX_NULL, 21, 21);
    test_owner_check("root's button, pen up", GX_NULL);
    EXPECT_EQ(2, test_root_button_events);
    EXPECT_EQ(0, test_button_events);
    test_position_check("root's button, pen up", 21, 21);

    /* 2. A button inside a window with no parent, the window followed by a
       canvas pointer where a root window keeps one.  */
    EXPECT_EQ(offsetof(GX_WINDOW_ROOT, gx_window_root_canvas), offsetof(TEST_TRAP, test_trap_canvas));
    memset(&test_trap_display, 0, sizeof(GX_DISPLAY));
    memset(&test_trap_canvas, 0, sizeof(GX_CANVAS));
    test_trap_canvas.gx_canvas_display = &test_trap_display;
    test_trap_canvas.gx_canvas_display_offset_x = 1000;
    test_trap_canvas.gx_canvas_display_offset_y = 1000;
    test_trap.test_trap_canvas = &test_trap_canvas;

    gx_utility_rectangle_define(&size, 70, 50, 150, 110);
    EXPECT_EQ(GX_SUCCESS, gx_window_create(&test_trap.test_trap_window, "test_window", GX_NULL, GX_STYLE_NONE, GX_ID_NONE, &size));
    gx_utility_rectangle_define(&size, 80, 60, 120, 80);
    EXPECT_EQ(GX_SUCCESS, gx_button_create(&test_button, "test_button", &test_trap.test_trap_window, GX_STYLE_ENABLED, GX_ID_NONE, &size));
    gx_widget_event_process_set(&test_button, test_button_event_process);

    test_button_events = 0;
    test_pen(GX_EVENT_PEN_DOWN, (GX_WIDGET *)&test_button, 90, 70);
    test_owner_check("window with no parent, pen down", (GX_WIDGET *)&test_button);
    test_pen(GX_EVENT_PEN_DRAG, GX_NULL, 91, 71);
    test_position_check("window with no parent, pen drag", 91, 71);
    test_pen(GX_EVENT_PEN_UP, GX_NULL, 92, 72);
    test_position_check("window with no parent, pen up", 92, 72);
    test_owner_check("window with no parent, pen up", GX_NULL);
    EXPECT_EQ(3, test_button_events);

    if (failed_tests)
    {
        gx_validation_print_test_result(TEST_FAIL);
    }
    else
    {
        gx_validation_print_test_result(TEST_SUCCESS);
    }

    exit(failed_tests);
}

VOID tx_application_define(void *first_unused_memory)
{
    tx_thread_create(&test_thread, "test_thread", test_thread_entry, 0,
                     test_thread_stack, sizeof(test_thread_stack),
                     1, 1, TX_NO_TIME_SLICE, TX_AUTO_START);
}

